#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int cap = 1, size = 0, doubles = 0;
    long moved = 0;
    const int N = 1024;

    printf("%-8s %-8s %-8s\n", "元素数", "新容量", "本次搬移");
    while (size < N) {
        if (size == cap) {                      /* 需要扩容 */
            int ncap = cap * 2;                 /* 倍数增长 */
            moved += size;                      /* 搬移现有元素 */
            printf("%-8d %-8d %-8d\n", size, ncap, size);
            cap = ncap; doubles++;
        }
        size++;
    }
    printf("\n插入 %d 个元素：扩容 %d 次，累计搬移 %ld 次\n", N, doubles, moved);
    printf("平均每次插入搬移 = %.3f 次（< 2，符合均摊 O(1)）\n", (double)moved / N);
    printf("反例：若每次只 +1 扩容，累计搬移会是 %d 次（O(n^2)）\n", N * (N - 1) / 2);
    return 0;
}
